-- DirectPath: government contribution schedules (SQL only, no PHP command needed)
-- Import this file in phpMyAdmin on the directpath_db database.
-- It replaces ONLY the contribution schedule tables listed below.
-- Rates are the published tables the system was prepared with; HR remains responsible for confirming them.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DELETE FROM `government_contribution_schedules`;

DELETE FROM `government_contribution_rules`;

DELETE FROM `sss_contribution_table`;

DELETE FROM `income_tax_brackets`;

DELETE FROM `income_tax_schedules`;

SET FOREIGN_KEY_CHECKS=1;
